-- Automatic concrete per-source clearing assignments. No source bytes or numeric values in receipts.
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.ctx07_emit_source_successors_v7(p_owner text,p_fence bigint,p_stop bigint)
RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $f$
DECLARE ctl jsonb;parent jsonb;review jsonb;q record;manifest jsonb;h text;k text;kind text;blocker text;assignment jsonb;ev bigint;n integer:=0;helper_hash text;qualification jsonb;qualification_event bigint;output_hash text;BEGIN
 ctl:=population_top3000_202608_202609_v1.continuation_guard_v6(p_owner,p_fence,p_stop);
 SELECT details INTO parent FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=17976 AND event='ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5';
 IF parent->>'assignment_id' IS DISTINCT FROM 'ctx07-original-source-recovery-numerical-vintage-v6' OR parent->>'owner_id' IS DISTINCT FROM p_owner OR parent->>'owner_fence' IS DISTINCT FROM p_fence::text OR parent->>'stop_generation' IS DISTINCT FROM p_stop::text OR parent->>'scope_sha256' IS DISTINCT FROM ctl->>'scope_sha256' OR parent#>>'{next_assignment_rule,must_append_concrete_event}' IS DISTINCT FROM 'true' OR nullif(parent->>'not_after','') IS NULL OR (parent->>'not_after')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION 'CTX07_SUCCESSOR_PARENT_AUTHORITY';END IF;
  ctl:=jsonb_set(ctl,'{not_after}',to_jsonb(least((ctl->>'not_after')::timestamptz,(parent->>'not_after')::timestamptz)));
 helper_hash:=encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx07_emit_source_successors_v7(text,bigint,bigint)'::regprocedure),'UTF8')),'hex');
 SELECT details INTO review FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='CTX07_V7_SUCCESSOR_DISPATCH_REVIEW' AND details->>'helper_function_sha256'=helper_hash ORDER BY event_id DESC LIMIT 1;
 IF review->>'approved' IS DISTINCT FROM 'true' OR nullif(review->>'reviewer','') IS NULL OR review->>'reviewer' IS NOT DISTINCT FROM review->>'producer' OR coalesce(review->>'code_commit','')!~'^[0-9a-f]{40}$' THEN RAISE EXCEPTION 'CTX07_SUCCESSOR_REVIEW_REQUIRED';END IF;
 FOR q IN SELECT r.request_key,r.source_id,b.raw_sha256,r.input_versions,
 CASE WHEN e.evidence->>'status'='NUMERICAL_PUBLICATION_RECONSTRUCTION_VERIFIED' THEN 'INDEPENDENT_VERIFICATION' WHEN e.evidence->>'status'='SOURCE_VERSION_DIFFERS' THEN 'SOURCE_RECOVERY' ELSE 'IMPLEMENTATION_REPAIR' END work_kind,
 jsonb_agg(jsonb_build_object('observation_id',e.observation_id,'evidence_sha256',e.evidence_sha256,'status',e.evidence->>'status','factor',e.evidence->>'factor_name','role',e.evidence->>'record_role','reference_period',e.evidence->>'reference_period') ORDER BY e.observation_id) units
 FROM population_top3000_202608_202609_v1.ctx07_recovery_evidence_v6 e JOIN population_top3000_202608_202609_v1.ctx07_recovery_request_v6 r USING(request_key) JOIN population_top3000_202608_202609_v1.ctx07_recovery_body_v6 b USING(request_key)
 GROUP BY r.request_key,r.source_id,b.raw_sha256,r.input_versions,work_kind ORDER BY r.request_key,work_kind LIMIT 79 LOOP
 IF rtrim(q.source_id) !~ '^[a-zA-Z0-9_]+$' OR q.input_versions->>'bundle_sha256' IS DISTINCT FROM population_top3000_202608_202609_v1.ctx07_recovery_bundle_v6() THEN RAISE EXCEPTION 'CTX07_SUCCESSOR_SOURCE_PIN_CHANGED';END IF;
 kind:=q.work_kind;blocker:=CASE kind WHEN 'INDEPENDENT_VERIFICATION' THEN 'CTX07_V7_EXACT_SOURCE_INDEPENDENT_REVIEW' WHEN 'SOURCE_RECOVERY' THEN 'CTX07_V7_ORIGINAL_VERSION_RECOVERY' ELSE 'CTX07_V7_EXACT_SOURCE_EXTRACTION_REQUIRED' END;
 manifest:=jsonb_build_array(jsonb_build_object('source_request_key',q.request_key,'source_id',q.source_id,'source_body_sha256',q.raw_sha256,'input_versions',q.input_versions,'observations',q.units,'required_population_units',79,'dictionary_series',21,'source_body_private',true));
 h:=encode(sha256(convert_to(manifest::text,'UTF8')),'hex');k:='ctx07-source-v7:'||kind||':'||h;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE clearing_id=k) THEN
 IF kind<>'INDEPENDENT_VERIFICATION' OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE clearing_id=k AND status='READY' AND attempts=0) THEN CONTINUE;END IF;
 SELECT assignment_event_id INTO ev FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE clearing_id=k;
 ELSE
 IF n>=16 OR (SELECT count(*) FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE status NOT IN('COMPLETE','SUPERSEDED'))>=96 THEN CONTINUE;END IF;
 assignment:=ctl||jsonb_build_object('assignment_id',k,'clearing_id',k,'parent_assignment_event_id',17976,'kind',kind,'family_id','CTX07','blocker_code',blocker,'assigned_executor','automation:6adc2c96db348191bca7cf4eacfdac32','exclusive_component','CTX07_SOURCE:'||q.source_id||':'||kind,'root_will_not_concurrently_modify',true,'repository','robert8p/market-data-leading-indicator-lab','code_commit',review->>'code_commit','input_manifest',manifest,'input_sha256',h,'source_input_versions',q.input_versions,'producer_role',CASE WHEN kind='INDEPENDENT_VERIFICATION' THEN 'Distinct numerical and temporal reviewer, never the source/parser producer' ELSE 'Exact source parser or recovery producer' END,'independent_reviewer_role','Distinct source/numerical/temporal reviewer; cannot self-certify',
 'concrete_required_output',CASE kind WHEN 'INDEPENDENT_VERIFICATION' THEN 'Independently inspect exact retained original bytes and pinned numerical evidence for these observation IDs; verify unique source numeric lexemes, units, reference dates, publication header, vintage identity and future exclusion. Persist component-only qualification or precise unresolved findings. Preserve the original receipt limitation and all unreviewed units.' WHEN 'SOURCE_RECOVERY' THEN 'Reconcile the exact current body against the frozen original hash for these observation IDs. Reuse retained private original versions; if absent, prepare a measured source-specific finite admission with distinct review before any new HTTP. Never certify current differing bytes as the original vintage.' ELSE 'Implement one independently reviewed extraction rule for exactly these observation IDs in this pinned original body. Preserve original evidence; append separately versioned numerical reconstruction with exact location, Decimal value, units, release and reference headers. Unsupported or ambiguous values remain explicit; no token-only matching.' END,
 'allowed_repository_files',jsonb_build_array('population_top3000_202608_202609/completion_20261024/continuity_v6/macro/'||q.source_id||'_parser_v7.sql','population_top3000_202608_202609/completion_20261024/continuity_v6/macro/'||q.source_id||'_parser_test_v7.sql','population_top3000_202608_202609/completion_20261024/continuity_v6/macro/'||q.source_id||'_review_v7.json'),
 'allowed_code_objects',jsonb_build_array('ctx07_'||q.source_id||'_extract_v7','ctx07_'||q.source_id||'_evidence_v7'),'maximum_elapsed_minutes',30,'maximum_tool_calls',80,'maximum_repair_iterations',2,'maximum_production_integrations',1,'new_provider_requests',0,'new_http_invocations',0,'maximum_source_bytes',0,'maximum_new_evidence_bytes',1048576,'maximum_observation_units',jsonb_array_length(q.units),
 'tests',jsonb_build_array('Exact raw body and observation/evidence hashes','Unique source-context numeric extraction and units using private original bytes','Reference period and release-vintage identity','As-of query rejects future revisions','Owner/fence/stop rejection and idempotent replay','Actual PostgreSQL rollback before parser integration; independent reviewer reruns changed risks'),
 'expected_useful_commit','Pinned independent qualification receipt or append-only exact-source numerical evidence for the listed observation IDs, with immutable output hashes','expected_successor',CASE WHEN kind='INDEPENDENT_VERIFICATION' THEN 'Root component qualification review; all other required units and VALIDATE evidence holds remain explicit' ELSE 'Distinct independent numerical/population/temporal review assignment for exact newly produced hashes' END,'family_acceptance_authorized',false,'serving_promotion_authorized',false,'protected_invariants',parent->'protected_invariants','next_assignment_rule',jsonb_build_object('permitted','Distinct independent verification of exactly this source unit; missing originals require separate finite reviewed source admission','new_source_requests_without_admission',false,'original_deadline_extension',false));
 INSERT INTO population_top3000_202608_202609_v1.continuation_clear_queue_v6(clearing_id,kind,family_id,blocker_code,input_manifest,input_sha256,status,owner_id,owner_fence,stop_generation,scope_sha256,not_after,last_receipt) VALUES(k,kind,'CTX07',blocker,manifest,h,'READY',p_owner,p_fence,p_stop,ctl->>'scope_sha256',(ctl->>'not_after')::timestamptz,jsonb_build_object('execution_recipe',assignment->>'concrete_required_output','component_assignment',true)) ON CONFLICT DO NOTHING;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5',assignment) RETURNING event_id INTO ev;
 UPDATE population_top3000_202608_202609_v1.continuation_clear_queue_v6 SET assignment_event_id=ev WHERE clearing_id=k;
 n:=n+1;
 END IF;
 -- Reuse an already completed distinct component review only for its exact current source output.
 IF kind='INDEPENDENT_VERIFICATION' THEN
 SELECT encode(sha256(convert_to(coalesce(string_agg(evidence_sha256,E'\n' ORDER BY observation_id),''),'UTF8')),'hex') INTO output_hash FROM population_top3000_202608_202609_v1.ctx07_recovery_evidence_v6 WHERE request_key=q.request_key;
 SELECT x.event_id,x.details INTO qualification_event,qualification FROM population_top3000_202608_202609_v1.pipeline_event x WHERE x.event='CTX07_V6_COMPONENT_QUALIFICATION_REVIEW' AND x.details->>'source_id'=q.source_id AND x.details->>'source_sha256'=q.raw_sha256 AND x.details->>'output_sha256'=output_hash AND x.details->>'decision'='QUALIFIED_COMPONENT_RECONSTRUCTION_WITH_REQUIRED_REVISION_HOLD' AND nullif(x.details->>'reviewer','') IS NOT NULL AND x.details->>'reviewer' IS DISTINCT FROM x.details->>'producer' AND x.details->>'live_evidence_hashes_all_recomputed'='true' AND x.details->>'source_body_independently_rehashed_live'='true' AND x.details->>'original_lexical_numeric_and_publication_headers_independently_rechecked'='true' AND x.details#>>'{evidence_status_counts,NUMERICAL_PUBLICATION_RECONSTRUCTION_VERIFIED}'=jsonb_array_length(q.units)::text AND x.details->>'strict_original_receipt_qualified'='false' AND x.details->>'family_accepted'='false' AND EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_commit c WHERE c.commit_id::text=x.details->>'useful_commit_id' AND c.output_sha256=output_hash AND c.new_committed_units>0 AND c.receipt->'immutable_output_ids' @> jsonb_build_array(q.request_key)) ORDER BY x.event_id DESC LIMIT 1;
 IF qualification_event IS NOT NULL THEN
 UPDATE population_top3000_202608_202609_v1.continuation_clear_queue_v6 SET status='COMPLETE',last_receipt=last_receipt||jsonb_build_object('reused_independent_review_event_id',qualification_event,'useful_commit_id',qualification->>'useful_commit_id','output_sha256',output_hash,'qualified_component_units',jsonb_array_length(q.units),'family_accepted',false),updated_at=clock_timestamp() WHERE clearing_id=k AND status='READY' AND attempts=0;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CTX07_V7_COMPONENT_REVIEW_REUSED',ctl||jsonb_build_object('assignment_event_id',ev,'clearing_id',k,'review_event_id',qualification_event,'output_sha256',output_hash,'component_units',jsonb_array_length(q.units),'remaining_units_unchanged',true,'family_accepted',false));
 END IF;END IF;
 END LOOP;
 RETURN jsonb_build_object('state','CTX07_CONCRETE_SUCCESSORS_DISPATCHED','new_assignments',n,'maximum_new_per_pass',16,'source_requests',0,'dataset_acceptance',false);
END;$f$;
REVOKE ALL ON FUNCTION population_top3000_202608_202609_v1.ctx07_emit_source_successors_v7(text,bigint,bigint) FROM PUBLIC,anon,authenticated;
